from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/eight-fighters';O.mkdir(parents=True,exist_ok=True);html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready');result=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,out=[];for(const id of INK.Schema.CHARACTERS)for(const m of A.moves[id].filter(m=>m.category==='normal'&&!m.air&&!m.throw&&!m.launch&&!m.knockdown&&(m.hits??1)===1)){A.start(id,id==='ryu'?'cammy':'ryu','training','classic',1);G.paused=true;document.getElementById('dummy').value='idle';document.getElementById('autohp').checked=false;A.teleport(0,300);A.teleport(1,1100);A.inputMove(0,m.id);let nearest=Infinity,farthest=0,frames=0;for(let i=0;i<100;i++){A.step();const a=A.fighters[0],d=A.fighters[1],g=A.geometry(a),h=A.geometry(d);if(g.hit.length)frames++;for(const hit of g.hit)for(const hurt of h.hurt){if(hit.y<hurt.y+hurt.h&&hit.y+hit.h>hurt.y){nearest=Math.min(nearest,hit.x-a.x-(hurt.x-d.x)-hurt.w);farthest=Math.max(farthest,hit.x+hit.w-a.x-(hurt.x-d.x));}}if(i>2&&!a.attack)break;}out.push({id,move:m.id,level:m.level,pose:m.pose,contactPart:m.contactPart,normalState:m.normalState,rangeAI:m.range,nearest,farthest,frames});}return out;}''');b.close();report={'htmlSha256':hashlib.sha256(html).hexdigest(),'scope':'Production active-frame AABB horizontal root-distance overlap for eight characters, against Ryu standing neutral (Ryu against Cammy). Calibration only, not collision authorization or whole-character reach guarantee.','rows':result};(O/'geometry-calibration.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
